preConditionHook:
// Level big bars (Brian's notes P1f, triage row P1). Pane 2. The P1 visit scan:
// a VISIT is a bar kk bars ago, minGap <= kk <= lookback, whose low..high range
// contains the current close (inclusive, el_le/el_ge). At least minVisits
// visits. Passes when the mean high - low of the visit bars is at least
// rangeAtr x the CURRENT ATR; negate for small bars. Identical both sides.
// WFSafe_AvgTrueRange: MultiWalk's ROLLING accumulator, SwingLowRejection's
// block verbatim -- seeded with a full N-term sum on the first calculated bar or
// when the length changes, and after that TWO statements (S += in; S -= out;) --
// EL evaluates S[1] + in - out left to right. It stays in the hook, which the
// generator emits unconditionally.
if (atrLenState != (int)atrLookback) {
    atrSum = 0.0;
    for (aa = 0; aa < (int)atrLookback; ++aa) {
        hiV = high[aa] > close[aa + 1] ? high[aa] : close[aa + 1];
        loV = low[aa] < close[aa + 1] ? low[aa] : close[aa + 1];
        atrSum += hiV - loV;
    }
    atrLenState = (int)atrLookback;
} else {
    outIdx = (int)atrLookback;
    hiV = high[0] > close[1] ? high[0] : close[1];
    loV = low[0] < close[1] ? low[0] : close[1];
    hiO = high[outIdx] > close[outIdx + 1] ? high[outIdx] : close[outIdx + 1];
    loO = low[outIdx] < close[outIdx + 1] ? low[outIdx] : close[outIdx + 1];
    atrSum += hiV - loV;
    atrSum -= hiO - loO;
}
atrValue = atrSum / (int)atrLookback;
visitCount = 0;
rangeSum = 0.0;
for (kk = (int)minGap; kk <= (int)lookback; ++kk) {
    if (el_le(low[kk], close[0]) && el_ge(high[kk], close[0])) {
        visitCount = visitCount + 1;
        rangeSum = rangeSum + (high[kk] - low[kk]);
    }
}
meanRange = 0.0;
if (visitCount > 0) meanRange = rangeSum / visitCount;
enoughVisits = el_ge(visitCount, minVisits) && el_gt(visitCount, 0);
